   if(outbound){const receipts={read:'✓✓ مقروءة',delivered:'✓✓ تم التسليم',sent:'✓ أُرسلت',accepted:'✓ قُبل الإرسال',failed:'تعذر الإرسال',uncertain:'الإرسال غير مؤكد',sending:'جارٍ الإرسال',historical:'سجل سابق'};meta.append(el('span','receipt '+(m.status||''),receipts[m.status]||'حالة التسليم غير متوفرة'));}wrap.append(meta);box.append(wrap);
