   if(action==='parse_mrz'){mrz.value='';draft.mrzIssues=[...(result.issues||result.errors||[])];if(result.fields&&(result.ok||(result.issues?.length&&result.issues.every(item=>item.code==='ambiguous_century')))){const parsed=result.fields;for(const path of ['passportNumber','nationalityCode','issuingCountryCode','birthDate','expiryDate','sex'])if(parsed[path])draft.fields[path]=parsed[path];if(parsed.latinNames?.family)draft.fields.latinFamilyName=parsed.latinNames.family;const given=parsed.latinNames?.givenNames;if(typeof given==='string'&&given.trim()&&!/[\s<]/.test(given.trim()))draft.fields.latinFirstName=given.trim();else if(Array.isArray(given)&&given.length===1&&typeof given[0]==='string'&&!/[\s<]/.test(given[0].trim()))draft.fields.latinFirstName=given[0].trim();else if(given){draft.fields.latinFirstName=null;draft.mrzIssues.push('يحتوي MRZ على عدة أسماء. طابق الاسم الأول واسم الأب والجد يدوياً مع الجواز.');}raadEdited(draft);draft.notice='نُسخت القيم المقروءة إلى المسودة فقط. تحقق منها واحفظها؛ لم تُسجل مراجعة الموظف.';}else draft.notice='لم يتأكد تحليل MRZ. راجع التنبيهات وأدخل البيانات يدوياً.';}
   else{raadAccept(draft,raadSummary(result));draft.notice=action==='review'?'حُفظ تأكيد مراجعة هذه النسخة. البوابة غير متصلة؛ لم يُقدّم طلب.':'حُفظت مسودة التجهيز. راجع الحقول والمستندات قبل تأكيدها.';}
